application.css:
* { box-sizing: border-box; }
:root { --ink:#172331; --muted:#718092; --line:#dce5eb; --teal:#168b82; --pale:#e8f5f2; --orange:#f28c62; }
body { margin:0; min-height:100vh; font-family: Inter, ui-sans-serif, system-ui, -apple-system, sans-serif; color:var(--ink); background:#f5f8f7; }
.page-shell { max-width:1120px; margin:auto; padding:54px 28px 28px; }
.hero { position:relative; padding:10px 2px 40px; }
.brand-mark { position:absolute; right:20px; top:4px; width:52px; height:52px; border-radius:16px; display:grid; place-items:center; color:white; font-size:26px; background:var(--teal); box-shadow:0 10px 22px #168b8230; }
.eyebrow { margin:0 0 9px; color:var(--teal); text-transform:uppercase; letter-spacing:.13em; font-size:11px; font-weight:800; }
h1,h2,p { margin-top:0; } h1 { margin-bottom:16px; font-size:clamp(39px,6vw,67px); line-height:.98; letter-spacing:-.055em; font-weight:800; } h1 span { color:var(--orange); } h2 { margin:0; font-size:25px; letter-spacing:-.03em; }
.intro { max-width:430px; color:var(--muted); font-size:16px; line-height:1.6; }
.workspace { display:grid; grid-template-columns:minmax(0,1.05fr) minmax(350px,.95fr); gap:22px; align-items:start; }
.booking-form,.bookings-panel { background:white; border:1px solid #e8eeee; border-radius:22px; padding:28px; box-shadow:0 15px 40px #18323808; }
.section-heading,.panel-heading { display:flex; justify-content:space-between; align-items:flex-start; margin-bottom:25px; } .required-note { color:#a0abb4; font-size:11px; }
.field-grid { display:grid; grid-template-columns:1fr 1fr; gap:18px 14px; } .field { display:flex; flex-direction:column; gap:8px; font-size:12px; font-weight:700; color:#526171; } .field-wide { grid-column:1/-1; } .field b { color:var(--orange); }
input,select { width:100%; border:1px solid var(--line); border-radius:10px; background:#fbfcfc; padding:13px 14px; color:var(--ink); font:inherit; outline:none; transition:.2s; } input:focus,select:focus { border-color:var(--teal); box-shadow:0 0 0 3px #168b8218; } select { cursor:pointer; }
.primary-button { margin-top:24px; border:0; border-radius:11px; padding:14px 18px; width:100%; color:#fff; background:var(--teal); font:700 14px inherit; cursor:pointer; transition:.2s; } .primary-button:hover { background:#10736d; transform:translateY(-1px); } .primary-button span { float:right; font-size:20px; line-height:12px; }
.count-badge { min-width:28px; height:28px; padding:0 8px; display:grid; place-items:center; border-radius:20px; color:var(--teal); background:var(--pale); font-size:12px; font-weight:800; }
.booking-list { display:flex; flex-direction:column; gap:12px; min-height:180px; } .empty-state { display:flex; flex-direction:column; align-items:center; justify-content:center; min-height:180px; text-align:center; color:var(--muted); } .calendar-icon { display:grid; place-items:center; width:40px; height:40px; margin-bottom:10px; border-radius:12px; color:var(--teal); background:var(--pale); font-size:25px; } .empty-state p { margin:0 0 4px; color:var(--ink); font-weight:700; } .empty-state small { font-size:12px; }
.booking-card { border:1px solid var(--line); border-left:4px solid var(--teal); border-radius:12px; padding:15px; } .booking-card.cancelled { border-left-color:#b5bec5; opacity:.65; } .card-top { display:flex; justify-content:space-between; gap:10px; } .customer { margin:0; font-weight:800; } .status { color:var(--teal); font-size:10px; text-transform:uppercase; letter-spacing:.1em; font-weight:800; } .cancelled .status { color:#89949d; } .details { margin:9px 0 14px; color:var(--muted); font-size:12px; line-height:1.6; } .cancel-button { border:0; padding:0; color:#c46b50; background:none; font:700 12px inherit; cursor:pointer; } .cancel-button:hover { text-decoration:underline; }
.confirmation { margin:-8px 0 17px; padding:11px 13px; border-radius:9px; color:#176b63; background:var(--pale); font-size:12px; font-weight:700; } .form-error { margin:16px 0 -8px; color:#c35446; font-size:12px; } footer { padding:25px 2px 0; color:#9aa6ad; text-align:center; font-size:11px; }
@media (max-width:760px) { .page-shell { padding:30px 16px 22px; } .workspace { grid-template-columns:1fr; } .hero { padding-bottom:28px; } .brand-mark { right:0; } }
@media (max-width:430px) { .field-grid { grid-template-columns:1fr; } .field-wide { grid-column:auto; } .booking-form,.bookings-panel { padding:21px; } }

application.javascript:
const form = document.getElementById('booking-form');
const dateInput = document.getElementById('booking-date');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const confirmation = document.getElementById('confirmation');
const error = document.getElementById('form-error');
const count = document.getElementById('booking-count');
let bookings = [];

function todayString() {
  const now = new Date();
  const offset = now.getTimezoneOffset() * 60000;
  return new Date(now.getTime() - offset).toISOString().slice(0, 10);
}

dateInput.min = todayString();

function formatDate(value) {
  return new Date(value + 'T00:00:00').toLocaleDateString(undefined, { weekday:'short', month:'short', day:'numeric', year:'numeric' });
}

function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(card => card.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = bookings.filter(item => !item.cancelled).length;
  bookings.forEach(item => {
    const card = document.createElement('article');
    card.className = 'booking-card' + (item.cancelled ? ' cancelled' : '');
    card.dataset.testid = 'booking';
    card.dataset.status = item.cancelled ? 'cancelled' : 'active';
    card.innerHTML = `<div class="card-top"><p class="customer" data-testid="booking-name-display"></p><span class="status">${item.cancelled ? 'Cancelled' : 'Confirmed'}</span></div><p class="details">${formatDate(item.date)} · ${item.time}<br>${item.type}</p>${item.cancelled ? '' : '<button class="cancel-button" data-testid="booking-cancel" type="button">Cancel booking</button>'}`;
    card.querySelector('[data-testid="booking-name-display"]').textContent = item.name;
    const cancel = card.querySelector('[data-testid="booking-cancel"]');
    if (cancel) cancel.addEventListener('click', () => { item.cancelled = true; render(); });
    list.appendChild(card);
  });
}

form.addEventListener('submit', event => {
  event.preventDefault();
  error.hidden = true;
  const data = new FormData(form);
  const name = data.get('name').trim();
  const email = data.get('email').trim();
  const date = data.get('date');
  const time = data.get('time');
  const type = data.get('type');
  if (!name || !email || !date || !time || !type || !form.checkValidity()) {
    error.textContent = 'Please complete all required fields with a valid email address.';
    error.hidden = false;
    form.reportValidity();
    return;
  }
  if (date < todayString()) {
    error.textContent = 'Please choose today or a future date.';
    error.hidden = false;
    return;
  }
  bookings.push({ name, email, date, time, type, cancelled:false });
  render();
  confirmation.textContent = `Booking confirmed for ${name}.`;
  confirmation.hidden = false;
  form.reset();
  dateInput.min = todayString();
  setTimeout(() => { confirmation.hidden = true; }, 5000);
});

render();
